#!/bin/sh
# Xcode Cloud: Not3.xcodeproj is generated by XcodeGen and not committed, so build it here.
set -euo pipefail

cd "$CI_PRIMARY_REPOSITORY_PATH"

brew install xcodegen
xcodegen generate

# Xcode Cloud never resolves packages on its own: it needs the pinned Package.resolved.
# Refresh Config/Package.resolved after updating packages locally (see README §16).
RESOLVED_DIR="Not3.xcodeproj/project.xcworkspace/xcshareddata/swiftpm"
if [ -f Config/Package.resolved ]; then
  mkdir -p "$RESOLVED_DIR"
  cp Config/Package.resolved "$RESOLVED_DIR/Package.resolved"
else
  echo "error: Config/Package.resolved is missing; Xcode Cloud cannot resolve Swift packages." >&2
  exit 1
fi
